/** Transcribed at total stake CZK20, MerkurXtip rules p50.
 * Pure evaluator only: weights, tumbles, art and UI are not connected yet. */
export const RHINO_SYMBOLS=['cheetah','gorilla','crocodile','hyena','flamingo','a','k','q','j','ten'] as const;
/** Indexed by consecutive reel count 0..6; multiples of total stake. */
export const RHINO_PAYS:readonly (readonly number[])[]=[
 [0,0,1,2,10,25,50], [0,0,0,1,2,2.5,5], [0,0,0,.3,.5,1,2.5],
 [0,0,0,.3,.5,.8,2], [0,0,0,.2,.4,.6,1.5],
 [0,0,0,.2,.4,.6,1.5], [0,0,0,.2,.4,.6,1.5],
 [0,0,0,.1,.2,.4,1], [0,0,0,.1,.2,.4,1], [0,0,0,.1,.2,.4,1],
];
export const RHINO_WILD=10,RHINO_SCATTER=11;
export interface RhinoBoard { columns:number[][]; top:number[]; }
export interface RhinoWin { symbol:number; reels:number; ways:number; cells:number[]; amount:number; }
/** Main cell id = col*7+row, top cell id=42+index. Logical IDs are stable
 * through changes in reel height; this is not the old fixed-row UI layout. */
export function rhinoEvaluate(board:RhinoBoard,bet:number){
 if(!Number.isFinite(bet)||bet<=0)throw Error('Invalid Rhino bet');
 if(board.columns.length!==6||board.top.length!==4)throw Error('Invalid Rhino reel layout');
 const columns=board.columns.map((symbols,col)=>{
  if(symbols.length<2||symbols.length>7)throw Error('Invalid Rhino reel height');
  return symbols.map((symbol,row)=>{
   if(!Number.isInteger(symbol)||symbol<0||symbol>RHINO_SCATTER||symbol===RHINO_WILD)throw Error('Invalid Rhino main symbol');
   return {symbol,cell:col*7+row};
  });
 });
 board.top.forEach((symbol,index)=>{
  if(!Number.isInteger(symbol)||symbol<0||symbol>RHINO_SCATTER)throw Error('Invalid Rhino top symbol');
  columns[index+1].push({symbol,cell:42+index});
 });
 const wins:RhinoWin[]=[];
 for(let symbol=0;symbol<RHINO_SYMBOLS.length;symbol++){
  let reels=0,ways=1;const cells:number[]=[];
  for(const col of columns){const matches=col.filter(c=>c.symbol===symbol||c.symbol===RHINO_WILD);if(!matches.length)break;reels++;ways*=matches.length;cells.push(...matches.map(c=>c.cell));}
  const pay=RHINO_PAYS[symbol][reels];if(pay)wins.push({symbol,reels,ways,cells,amount:bet*pay*ways});
 }
 const payout=wins.reduce((sum,w)=>sum+w.amount,0);
 if(!Number.isFinite(payout))throw Error('Rhino payout overflow');
 return {wins,payout,ways:columns.reduce((n,col)=>n*col.length,1),scatterCells:columns.flatMap(col=>col.filter(c=>c.symbol===RHINO_SCATTER).map(c=>c.cell)),removedCells:[...Array.from(new Set(wins.flatMap(w=>w.cells)))]};
}
