/** Explicit local audit imports only. This registry never feeds the lobby or
 * player ownership, and its schematic runs cannot pass production art QA. */
export function schematicDraftSlots(ids:string[],params:URLSearchParams):SlotMain[]{
 const result:SlotMain[]=[...gapSlots(),...tumbleSlots()].filter(slot=>ids.includes(slot.config.id)).map(slot=>{const outcome=params.get('audit-outcome');if(slot instanceof TumbleGame&&(outcome==='retrigger'||outcome==='full-board'&&slot.config.id==='signal-stack-ruins')){const seeds:Record<string,number>=outcome==='full-board'?{'signal-stack-ruins':175855144}:{'orbital-crystal-core':2436419252,'buried-gate-chambers':2930963218,'parrot-frontier':512928,'rose-orbit-voyage':2453883373,'glyph-archive':782779348};if(!seeds[slot.config.id])throw Error('No retrigger in this tumble game');slot.bonusDemoSpin=bet=>{const result=slot.spin(bet,tumbleRng(seeds[slot.config.id]));if(outcome==='retrigger'?!result.rounds?.some(r=>r.freeSpinsAdded):!result.rounds?.some(r=>r.tumbleFeature?.frames.some(f=>f.caption.includes('전판 완성 · 남은 회전 정산'))))throw Error('Recorded natural retrigger changed');return result;};}if(outcome==='no-win'||outcome==='multi-win')slot.demoSpin=bet=>{const rng=gapRng(983);for(let i=0;i<100000;i++){const r=slot.spin(bet,rng);if(!r.rounds&&(outcome==='no-win'?r.payout===0:r.wins.length>1))return r;}throw Error('Draft outcome unavailable: '+outcome);};return slot;});
 if(ids.includes('slot-o-mania'))result.push(new TrainPreviewSlot(params.get('audit-train')||'free'));
 if(ids.includes('golden-club-league'))result.push(new CavePreviewSlot(params.get('audit-cave')||'free'));
 if(ids.includes('realtime-vegas'))result.push(new ClassicPreviewSlot(params.get('audit-classic')||'multiple'));
 if(ids.includes('huuuge-jackpot-club'))result.push(new QuickPreviewSlot(params.get('audit-quick')||'pick'));
 if(ids.includes('billionaire-loop'))result.push(new PhoenixPreviewSlot(params.get('audit-phoenix')||'stack'));
 if(ids.includes('spin-it-gold'))result.push(new OilPreviewSlot(params.get('audit-oil')||'pick'));
 if(ids.includes('double-lucky'))result.push(params.get('audit-digit')==='engine'?new DigitSlot():new DigitPreviewSlot(params.get('audit-digit')||'boost'));
 if(ids.includes('jackpot-rich-night'))result.push(new TowerPreviewSlot(params.get('audit-tower')||'coins'));
 return result;
}
export function isSchematicDraft(slot:SlotMain){return slot instanceof TumbleGame||slot instanceof GapSlot||slot instanceof TrainPreviewSlot||slot instanceof CavePreviewSlot||slot instanceof ClassicPreviewSlot||slot instanceof QuickPreviewSlot||slot instanceof PhoenixPreviewSlot||slot instanceof OilPreviewSlot||slot instanceof DigitPreviewSlot||slot instanceof TowerPreviewSlot;}
