/** Moon's match-three board uses straight runs, not flood-filled clusters.
 * Keep this evaluator independent until the original paytable and presentation
 * have been checked; it is not a replacement for the whole bonus state machine.
 */
export interface MoonRun {symbol:number;cells:number[];multiple:number;}
export interface MoonPayRules {
 regular:number[][];
 wild:number[];
 mixedPrincess:number[];
}
/** Original in-game paytable screenshots: low symbols at bet1, guardians and
 * WILD at bet100. Values normalized to total-bet multiples (see research doc). */
export const MOON_PAYS:MoonPayRules={
 regular:[[.3,1,10],[.3,1,10],[.3,1,10],[.15,.3,3],[.15,.3,3],[.1,.2,2],[.1,.2,2]],
 wild:[1,3,50],mixedPrincess:[.2,.5,5],
};
/** Symbols 0..2 are guardians, 3..6 items, 7 WILD, -1 empty.
 * Pay rows are indexed by run length minus three.
 */
export function moonRuns(board:number[],pays:MoonPayRules):MoonRun[]{
 if(board.length!==25||board.some(n=>!Number.isInteger(n)||n < -1||n>7))throw Error('Moon requires a valid 5 × 5 board');
 const wins:MoonRun[]=[];
 for(let axis=0;axis<2;axis++)for(let fixed=0;fixed<5;fixed++){
  const line=Array.from({length:5},(_,i)=>axis?i*5+fixed:fixed*5+i),candidates:MoonRun[]=[];
  for(let symbol=0;symbol<9;symbol++){
   const matches=(value:number)=>value===7||(symbol===8?value>=0&&value<=2:value===symbol);
   let start=0;
   while(start<5){
    if(!matches(board[line[start]])){start++;continue;}
    let end=start+1;while(end<5&&matches(board[line[end]]))end++;
    const cells=line.slice(start,end),row=symbol===8?pays.mixedPrincess:symbol===7?pays.wild:pays.regular[symbol];
    const multiple=cells.length>=3?row?.[cells.length-3]||0:0;
    if(multiple>0)candidates.push({symbol,cells,multiple});start=end;
   }
  }
  // The same stretch must not pay once per possible wild substitution.
  candidates.sort((a,b)=>b.multiple-a.multiple||b.cells.length-a.cells.length||a.symbol-b.symbol);
  const accepted:MoonRun[]=[];
  for(const candidate of candidates){
   if(accepted.some(win=>candidate.cells.every(cell=>win.cells.includes(cell))||win.cells.every(cell=>candidate.cells.includes(cell))))continue;
   accepted.push(candidate);
  }
  wins.push(...accepted);
 }
 return wins;
}

export interface MoonFall {from:number;to:number;symbol:number;}
/** Collapse remaining symbols only. A Moon drop must never refill emptied
 * spaces: clearing all 25 initial symbols is a feature trigger. */
export function moonCollapse(board:number[],removed:Iterable<number>,createdWilds:Iterable<number>=[]){
 const source=[...board];for(const cell of removed)source[cell]=-1;
 for(const cell of createdWilds)source[cell]=7;
 const after=Array<number>(25).fill(-1),drops:MoonFall[]=[];
 for(let col=0;col<5;col++){
  const kept=Array.from({length:5},(_,row)=>row*5+col).filter(cell=>source[cell]>=0);
  kept.forEach((from,i)=>{const to=(5-kept.length+i)*5+col;after[to]=source[from];drops.push({from,to,symbol:source[from]});});
 }
 return{board:after,drops};
}

export type MoonPower=0|1|2;
export interface MoonPowerEvent {power:MoonPower;before:number[];after:number[];cells:number[];fromSymbol?:number;toSymbol?:number;}
/** The caller records choices in the result. Presentation never rerolls powers. */
export function moonPower(board:number[],power:MoonPower,rng:()=>number):MoonPowerEvent{
 const before=[...board],after=[...board],cells:number[]=[];
 const kinds=[...Array.from(new Set(board.filter(n=>n>=0&&n<7)))];
 const take=<T>(items:T[])=>items[Math.min(items.length-1,Math.floor(rng()*items.length))];
 let fromSymbol:number|undefined,toSymbol:number|undefined;
 if(power===0&&kinds.length>1){
  fromSymbol=take(kinds);toSymbol=take(kinds.filter(n=>n!==fromSymbol));
  after.forEach((n,i)=>{if(n===fromSymbol){after[i]=toSymbol!;cells.push(i);}});
 }else if(power===1){
  const count=rng()<.5?1:2;
  for(let turn=0;turn<count;turn++){
   const candidates=after.flatMap((n,i)=>n>=0&&n<7?[i]:[]);if(!candidates.length)break;
   // Prefer a location that bridges an existing pair. This choice rule is our
   // deterministic interpretation; original placement probabilities are private.
   const score=(cell:number)=>{
    let best=0;
    for(const step of [1,5])for(let offset=-2;offset<=0;offset++){
     const run=[cell+offset*step,cell+(offset+1)*step,cell+(offset+2)*step];
     if(run.some(i=>i<0||i>=25)||step===1&&run.some(i=>Math.floor(i/5)!==Math.floor(cell/5)))continue;
     const others=run.filter(i=>i!==cell).map(i=>after[i]);
     if(others.every(n=>n>=0)&&(others[0]===others[1]||others.includes(7)))best++;
    }return best;
   };
   const scores=candidates.map(score),best=Math.max(...scores),cell=take(candidates.filter((_,i)=>scores[i]===best));
   after[cell]=7;cells.push(cell);
  }
 }else if(power===2){
  const pool=[...kinds],selected:number[]=[];
  while(pool.length&&selected.length<2){const symbol=take(pool);selected.push(symbol);pool.splice(pool.indexOf(symbol),1);}
  after.forEach((n,i)=>{if(selected.includes(n)){after[i]=-1;cells.push(i);}});
 }
 return{power,before,after,cells,fromSymbol,toSymbol};
}

export interface MoonStage {
 before:number[];after:number[];runs:MoonRun[];awards:number[];payout:number;
 multiplierBefore:number;multiplierAfter:number;meterBefore:number;meterAfter:number;
 removed:number[];createdWilds:number[];drops:MoonFall[];power?:MoonPowerEvent;
}
export interface MoonRoundOptions {
 board:number[];pays:MoonPayRules;bet:number;limit:number;rng:()=>number;
 multiplier?:number;meter?:number;powers?:MoonPower[];settle?:(amount:number)=>number;
}
/** One initial board, finite removals and a finite power queue. The enclosing
 * game owns Trinity's fresh board, free-spin selection and carried multiplier. */
export function moonRound(o:MoonRoundOptions){
 let board=[...o.board],multiplier=o.multiplier??1,meter=o.meter??0,left=o.limit;
 const stages:MoonStage[]=[],powers=[...(o.powers||[])];let payout=0;
 for(let step=0;step<128;step++){
  const before=[...board],runs=moonRuns(board,o.pays),multiplierBefore=multiplier,meterBefore=meter;
  const removed=new Set<number>(),createdWilds=new Set<number>(),awards:number[]=[];let award=0,power:MoonPowerEvent|undefined;
  if(runs.length){
   for(const run of runs){
    const amount=Math.min(left,(o.settle??Math.round)(o.bet*run.multiple*multiplier));
    left-=amount;award+=amount;awards.push(amount);run.cells.forEach(c=>removed.add(c));
    if(run.cells.length===3)createdWilds.add(run.cells[1]);
    if(run.symbol<3||run.symbol===8)meter=Math.min(3,meter+run.cells.length-2);
   }
   multiplier=Math.min(20,multiplier+1);
  }else{
   const occupied=board.flatMap((n,i)=>n>=0?[i]:[]);
   if(occupied.length&&occupied.every(i=>board[i]===7))occupied.forEach(i=>removed.add(i));
   else if(occupied.length&&powers.length){power=moonPower(board,powers.shift()!,o.rng);board=[...power.after];}
   else break;
  }
  const collapse=moonCollapse(board,removed,createdWilds);board=collapse.board;payout+=award;
  stages.push({before,after:[...board],runs,awards,payout:award,multiplierBefore,multiplierAfter:multiplier,meterBefore,meterAfter:meter,removed:[...Array.from(removed)],createdWilds:[...Array.from(createdWilds)],drops:collapse.drops,power});
  if(left<=0||board.every(n=>n<0))break;
  if(step===127)throw Error('Moon board did not converge');
 }
 return{board,payout,multiplier,meter,stages,cleared:board.every(n=>n<0)};
}

export const MOON_INITIAL_SPINS=[4,5,8] as const;
export const MOON_EXTRA_SPINS=[4,3,2] as const;
export interface MoonSequenceOptions {
 bet:number;pick:()=>number;rng:()=>number;guardian:MoonPower;choice:MoonPower;
 powerChance:number;opening?:number[];limit?:number;settle?:(amount:number)=>number;
}
export type MoonResolvedRound=ReturnType<typeof moonRound>&{
 mode:'base'|'trinity'|'free';guardian:MoonPower;opening:number[];
 freeSpinsAdded:number;freeSpinsRemaining:number;clearAward:number;
};
/** Keeps the three distinct phases separate. Trinity is one fresh board with
 * a three-power queue, not an ordinary free spin with a renamed popup. */
export function moonSequence(o:MoonSequenceOptions){
 const limit=o.limit??o.bet*5000,rounds:MoonResolvedRound[]=[];let paid=0;
 const make=(mode:MoonResolvedRound['mode'],guardian:MoonPower,multiplier:number,powers:MoonPower[],opening=Array.from({length:25},o.pick),meter=0)=>{
  const result=moonRound({board:opening,pays:MOON_PAYS,bet:o.bet,limit:limit-paid,rng:o.rng,multiplier,meter,powers,settle:o.settle});
  const clearAward=mode==='free'&&result.cleared?Math.min(limit-paid-result.payout,o.bet*100):0;
  const round:MoonResolvedRound={...result,payout:result.payout+clearAward,clearAward,opening:[...opening],mode,guardian,freeSpinsAdded:0,freeSpinsRemaining:0};
  rounds.push(round);paid+=round.payout;return round;
 };
 const opening=o.opening??Array.from({length:25},o.pick);
 const base=make('base',o.guardian,1,!moonRuns(opening,MOON_PAYS).length&&o.rng()<o.powerChance?[o.guardian]:[],opening);
 let trigger=base;
 if(!base.cleared&&base.meter>=3&&paid<limit)trigger=make('trinity',o.guardian,1,[0,1,2]);
 const initial=trigger.cleared&&paid<limit?MOON_INITIAL_SPINS[o.choice]:0;
 let remaining:number=initial,awarded:number=initial,carried=trigger.multiplier,carriedMeter=0;
 while(remaining>0&&paid<limit){
  remaining--;const round=make('free',o.choice,carried,[o.choice],undefined,carriedMeter);carried=round.multiplier;
  const extra=round.meter>=3?Math.min(MOON_EXTRA_SPINS[o.choice],20-awarded):0;
  carriedMeter=round.meter>=3?0:round.meter;awarded+=extra;remaining+=extra;round.freeSpinsAdded=extra;round.freeSpinsRemaining=remaining;
 }
 return{rounds,payout:paid,freeSpinsAwarded:initial,choice:o.choice,nextGuardian:((o.guardian+(base.stages.some(s=>s.power)?1:0))%3) as MoonPower};
}
