import type {Perk,PerkCondition} from './CostumePerks';

// Editorial accessibility weights for shop pricing, not measured odds or RTP.
const accessibility:Record<PerkCondition,number>={hit:100,big:80,super:65,mega:50,amazing:35,streak2:75,streak3:55,five:55,multi:80,four:50,cascade3:70,cascade5:40,comeback:70,small:50};
/** Price finalized perks after normalization; return integer ticket tenths. */
export function costumePrice(perk:Perk|undefined,pet=false):number{
 const magnitude=perk?(perk.currency==='coins'?perk.bps:perk.bps/100):0;
 const score=perk?magnitude*accessibility[perk.condition]:0;
 if(pet)return score>=1900?5000:score>=1400?4000:score>=900?3000:2000;
 return score>=1600?3000:score>=900?1800:1200;
}
