import {features} from '../services/FeatureFlags';
import {i18n,tr} from '../services/Localization';
import {Node,Graphics,Color,UITransform,Label,Font,BlockInputEvents,Vec3,tween} from 'cc';
import {uiIcon} from './UIIcons';
/** Shared, centered entry/exit presentation. Never mutates the wallet or autoplay. */
export class FreeSpinPopup {
 readonly root:Node;
 constructor(parent:Node,width:number,height:number,contentWidth:number,font:Font|null,mode:'entry'|'exit',count:number,payout:number,title:string,onContinue:()=>void,tickets=0,presentation?:{title?:string;amount?:string;detail?:string}){
  const root=this.root=new Node('Free spins '+mode);root.layer=parent.layer;parent.addChild(root);
  const node=(name:string,x:number,y:number,w:number,h:number)=>{const n=new Node(name);n.layer=root.layer;root.addChild(n);n.setPosition(x,y);n.addComponent(UITransform).setContentSize(w,h);return n;};
  const rect=(name:string,x:number,y:number,w:number,h:number,color:string)=>{const n=node(name,x,y,w,h),g=n.addComponent(Graphics);g.fillColor=new Color(color);g.rect(-w/2,-h/2,w,h);g.fill();return n;};
  // Keep the running game visible. This transparent input guard prevents an
  // accidental spin without painting a full-screen modal backdrop.
  const guard=node('Free spins input guard',0,0,width,height);guard.addComponent(BlockInputEvents);
  const w=Math.min(contentWidth-80,480),h=Math.min(height*.50,342),accent=mode==='entry'?'#86ead0':'#ffd16f',secondary=mode==='entry'?'#bca7ff':'#ff9cc8';
  rect('Frame shadow',8,-10,w+12,h+12,'#111220');rect('Outer glow',0,0,w+6,h+6,'#67557d');rect('Gold frame',0,0,w,h,accent);const panel=rect('Free spins plaque',0,0,w-10,h-10,'#302c4b');
  rect('Inner top',0,h/2-9,w-28,5,secondary);rect('Inner bottom',0,-h/2+9,w-28,5,secondary);
  const labelAt=(name:string,value:string,x:number,y:number,width:number,size:number,color:string)=>{const n=node(name,x,y,width,size*1.5),l=n.addComponent(Label);if(font)l.font=font;else l.fontFamily=i18n.fontFamily;l.string=tr(value);l.fontSize=size;l.lineHeight=size*1.2;l.color=new Color(color);l.horizontalAlign=Label.HorizontalAlign.CENTER;l.verticalAlign=Label.VerticalAlign.CENTER;l.overflow=Label.Overflow.SHRINK;l.enableWrapText=false;n.getComponent(UITransform)!.setContentSize(width,size*1.5);return n;};
  const label=(name:string,value:string,y:number,size:number,color:string)=>labelAt(name,value,0,y,w-42,size,color);
  // Reuse the game's pixel wordmark and coin motif as the brand lockup.
  const logo=node('In My Pocket brand',0,h/2-29,w-56,26);const brand=logo.addComponent(Label);if(font)brand.font=font;else brand.fontFamily=i18n.fontFamily;brand.string=tr('인마이포켓');brand.fontSize=20;brand.color=new Color('#fff0c7');brand.horizontalAlign=Label.HorizontalAlign.CENTER;brand.verticalAlign=Label.VerticalAlign.CENTER;
  const coin=node('Brand coin',-Math.min(84,w*.27),h/2-29,22,22);uiIcon(coin.addComponent(Graphics),'coin',20);
  rect('Brand divider',0,h/2-50,w-48,2,'#7b6d83');
  const banner=rect('Feature banner',0,h/2-72,w-76,34,'#4c4167');
  label('Feature title',mode==='entry'?(presentation?.title||'FREE SPINS'):'축하합니다!',h/2-72,mode==='entry'?23:28,accent);
  const ticketText=tickets?(tickets/10).toFixed(1).replace(/\.0$/,'')+'T':'0T';
  if(mode==='entry'){
   const medal=rect('Entry medal',0,3,presentation?.amount?190:104,86,'#4a4266');uiIcon(node('Entry feature icon',0,30,22,22).addComponent(Graphics),'star',22);
   label('Free spins amount',presentation?.amount||count+'회',-13,36,'#fff2ce');
   // Keep the explanation visually separate from the large spin count. The
   // previous 15px line at -39 read like a suffix attached to the number.
   label('Free spins detail',presentation?.detail||title+' · 지급',-54,18,'#bfe6df');
   medal.setScale(.82,.82,1);tween(medal).delay(.08).to(.24,{scale:new Vec3(1,1,1)},{easing:'backOut'}).start();
  }else if(!features.tickets){
   rect('Coin result card',0,-2,w-70,68,'#413b59');label('Coin result',payout.toLocaleString()+' C',2,32,'#ffe19a');label('Free spins detail',presentation?.detail||count+'회 · 보너스 획득 완료',-48,15,'#bfe6df');
  }else{
   const cardW=(w-70)/2,cy=-2;
   const coinCard=rect('Coin result card',-(cardW+10)/2,cy,cardW,68,'#413b59'),ticketCard=rect('Ticket result card',(cardW+10)/2,cy,cardW,68,'#413b59');
   uiIcon(node('Coin result icon',-cardW+18,cy+10,26,26).addComponent(Graphics),'coin',24);uiIcon(node('Ticket result icon',10,cy+10,26,26).addComponent(Graphics),'ticket',24);
   labelAt('Coin result',payout.toLocaleString()+' C',-(cardW+10)/2,cy+4,cardW-42,28,'#ffe19a');
   labelAt('Ticket result','+'+ticketText,(cardW+10)/2,cy+4,cardW-42,28,'#ffb5db');
   label('Free spins detail',presentation?.detail||count+'회 · 보너스 획득 완료',-48,15,'#bfe6df');
   for(const [card,delay] of [[coinCard,.08],[ticketCard,.16]] as [Node,number][]){card.setScale(.82,.82,1);tween(card).delay(delay).to(.24,{scale:new Vec3(1,1,1)},{easing:'backOut'}).start();}
  }
  const button=rect('Continue free spins',0,-h/2+46,w-54,64,mode==='entry'?'#86d5bf':'#efc675');label('Continue label',mode==='entry'?'시작':'확인',-h/2+46,19,'#242a39');button.on(Node.EventType.TOUCH_END,(event:any)=>{event.propagationStopped=true;onContinue();});
  for(const side of [-1,1])for(let i=0;i<4;i++){const sparkle=rect('Pixel sparkle',side*(w/2-24),58-i*36,i%2?6:9,i%2?6:9,i%2?secondary:accent);sparkle.setScale(.6,.6,1);tween(sparkle).delay(i*.08).to(.25,{scale:new Vec3(1.35,1.35,1)}).to(.25,{scale:new Vec3(.65,.65,1)}).union().repeatForever().start();}
  for(const sx of [-1,1])for(const sy of [-1,1]){rect('Frame corner horizontal',sx*(w/2-24),sy*(h/2-18),28,5,'#fff1bd');rect('Frame corner vertical',sx*(w/2-14),sy*(h/2-28),5,28,'#fff1bd');}
  panel.setScale(.92,.92,1);banner.setScale(.88,1,1);tween(panel).to(.26,{scale:new Vec3(1,1,1)},{easing:'backOut'}).start();tween(banner).delay(.06).to(.22,{scale:new Vec3(1,1,1)},{easing:'backOut'}).start();
 }
 close(){this.root.removeFromParent();this.root.destroy();}
}
