import {SlotMain,SlotConfig,SpinResult} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
import {towerSequence,towerSymbol as s,TowerCoin,TowerChoice} from './TowerFeature';
export class TowerPreviewSlot extends SlotMain {
 constructor(private readonly fixture='coins'){super();}
 readonly columns=5;readonly rows=3;readonly mode='lines' as const;readonly paylines:number[][]=[];readonly bets=[...BET_LEVELS];
 readonly config:SlotConfig={id:'jackpot-rich-night',title:'골든 캐시 스파이어',subtitle:'GOLDEN CASH SPIRE',tag:'무료 피처 초안',color:'#33233c',accent:'#f0c576',description:'가려진 코인을 열어 회전 추가\n시작 표식에서 금액 코인 회전\n착지한 코인은 자리에 고정\n모든 회전 뒤 한 번씩 수집',symbols:[['coin','금액 코인'],['bar','BAR'],['bell','종'],['cherry','체리'],['bag','머니백'],['cash','지폐'],['seven','7'],['diamond','보석'],['wild','WILD'],['void','']].map(([id,name])=>({id:s(id),name,color:'#f0c576',weight:0,payout:0}))};
 artResource(id:string){if(!this.config.symbols.some(symbol=>symbol.id===id))throw Error('Unknown Tower art');return 'slot-art-handcrafted-v1/jackpot-rich-night/'+id.slice('jackpot-rich-night-'.length);}
 spin():SpinResult{throw Error('Tower draft is free playback only');}
 demoSpin(bet:number):SpinResult{
  if(!this.bets.includes(bet))throw Error('Invalid bet');
  const initial:TowerCoin[]=[1,3,4,6,11,14].map(cell=>({cell,amount:bet*2}));
  const board=Array.from({length:15},(_,cell)=>s(initial.some(c=>c.cell===cell)?'coin':['bell','bar','bag'][cell%3]));
  const choices:TowerChoice[]=this.fixture==='play-first'?[{cell:9,kind:'play'}]:[{cell:7,kind:'spins',added:2},{cell:2,kind:'spins',added:1},{cell:9,kind:'play'}];
  const turns:TowerCoin[][]=Array.from({length:this.fixture==='play-first'?6:9},()=>[]);
  if(this.fixture!=='no-new'){turns[0]=[{cell:2,amount:bet*2},{cell:7,amount:bet}];turns[2]=[{cell:8,amount:bet*8},{cell:13,amount:bet}];turns[4]=[{cell:0,amount:bet},{cell:9,amount:bet*2}];}
  return towerSequence(board,initial,choices,turns,bet);
 }
}
