export function uiIcon(g:Graphics,id:string,size:number,color='#e6dbff'){
 const rows=shapes[id]||shapes.help,u=size/12,palette:Record<string,string>={a:color,y:'#ffd16c',k:'#755024',w:'#fff4ce'};
 rows.forEach((row,y)=>Array.from(row).forEach((c,x)=>{if(!palette[c])return;g.fillColor=new Color('#171628');g.rect((x-6)*u-u*.18,(rows.length/2-y-1)*u-u*.18,u*1.36,u*1.36);g.fill();}));
 rows.forEach((row,y)=>Array.from(row).forEach((c,x)=>{if(!palette[c])return;g.fillColor=new Color(palette[c]);g.rect((x-6)*u,(rows.length/2-y-1)*u,u,u);g.fill();}));
}
