import {OathbladeSlot} from './OathbladeSlot';
export function oathbladeAudit(params:URLSearchParams){const slot=new OathbladeSlot(),outcome=params.get('audit-outcome');
 const find=(bet:number,bonus:boolean)=>{let seed=349281;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};for(let i=0;i<100000;i++){const r=slot.spin(bet,rng);if(bonus?r.rounds?.some(r=>r.freeSpinsAdded):!r.rounds&&(outcome==='no-win'?r.wins.length===0:outcome==='single-win'?r.wins.length===1:r.wins.length>1))return r;}throw Error('Oath audit unavailable');};
 if(['no-win','single-win','multi-win'].includes(outcome||''))slot.demoSpin=bet=>find(bet,false);
 if(outcome==='extra')slot.bonusDemoSpin=bet=>find(bet,true);return slot;}
