import {tomeRound,TomeRound} from './TomeFeature';
import {tomeSequenceResult} from './TomeResult';
import type {SpinResult} from './SlotMain';

/** Our own sampling weights; the source game's private reel math is not public.
 * These are provisional until independent distribution/purchase calibration.
 * 0..7 regular,8 book,9 portrait. Mega is awarded by the eye feature only. */
export const TOME_WEIGHTS=[5,6,7,8,12,14,16,18,.4,.2] as const;
export function tomeSampler(rng:()=>number){
 const roll=()=>{const n=rng();if(!Number.isFinite(n)||n<0||n>=1)throw Error('Invalid Tome RNG');return n;};
 const pick=()=>{let n=roll()*TOME_WEIGHTS.reduce((sum,w)=>sum+w,0);for(let i=0;i<TOME_WEIGHTS.length;i++){n-=TOME_WEIGHTS[i];if(n<0)return i;}return 9;};
 const eyes=(count:number)=>{const cells=Array.from({length:25},(_,i)=>i),chosen:number[]=[];for(let i=0;i<count;i++){const index=Math.floor(roll()*cells.length);chosen.push(cells.splice(index,1)[0]);}return chosen.sort((a,b)=>a-b);};
 return{roll,pick,eyes,board:()=>Array.from({length:25},pick)};
}
/** One natural wager, one state-generated base sequence and at most one Other
 * World. Remaining max-win budget is shared, never reset on bonus entry. */
export function tomeGame(bet:number,rng:()=>number=Math.random,opening?:number[]):SpinResult{
 const sample=tomeSampler(rng),limit=bet*2000;
 const base=tomeRound({board:opening??sample.board(),bet,mode:'base',eyes:sample.roll()<.12?sample.eyes(1):[],pick:sample.pick,rng:sample.roll,limit});
 let bonus:TomeRound|undefined;
 if(base.effectsAwarded&&base.payout<limit){
  bonus=tomeRound({board:sample.board(),bet,mode:'other-world',eyes:sample.eyes(sample.roll()<.5?11:12),effects:base.effectsAwarded,pick:sample.pick,rng:sample.roll,limit:limit-base.payout});
 }
 return tomeSequenceResult('tome-of-madness',bet,base,bonus);
}
