import type {SpinResult,Win} from './SlotMain';
export const PHOENIX_SYMBOLS=['crane','lantern','lotus','bonsai','a','k','q','j','ten','nine','bell-scatter','phoenix-wild'] as const;
export const phoenixSymbol=(name:string)=>'billionaire-loop-'+name;
export interface PhoenixTurn {board:string[];wins:Win[];extraSpins?:number;}
export interface PhoenixPlayback {triggerBoard:string[];triggerCells:number[];triggerWins:Win[];awarded:number;stages:{before:string[];board:string[];stacks:{column:number;cells:number[]}[];wilds:number[];wins:Win[];remainingBefore:number;remainingConsumed:number;remainingAfter:number;added:number}[];}
function boardOK(board:string[]){if(board.length!==15||board.some(id=>!PHOENIX_SYMBOLS.some(name=>phoenixSymbol(name)===id)))throw Error('Invalid phoenix board');}
function winsCopy(wins:Win[]){return wins.map(win=>{if(!Number.isSafeInteger(win.amount)||win.amount<1||!win.cells.length||new Set(win.cells).size!==win.cells.length||win.cells.some(cell=>!Number.isInteger(cell)||cell<0||cell>=15))throw Error('Invalid phoenix win');return {...win,cells:[...win.cells]};});}
/** Phoenix Garden observed stacked golden wilds are individual symbols, not
 * one giant icon and not sticky. No rebirth/hold feature is inferred by name. */
export function phoenixFreeSequence(triggerBoard:string[],triggerInput:Win[],awarded:number,turns:PhoenixTurn[],bet:number):SpinResult{
 boardOK(triggerBoard);const triggerCells=triggerBoard.flatMap((id,cell)=>id===phoenixSymbol('bell-scatter')?[cell]:[]);
 if(triggerCells.length<3||!Number.isSafeInteger(awarded)||awarded<1||awarded>1000||!Number.isSafeInteger(bet)||bet<1)throw Error('Invalid phoenix trigger');
 let remaining=awarded,previous=[...triggerBoard];const triggerWins=winsCopy(triggerInput),wins=[...triggerWins],stages:PhoenixPlayback['stages']=[];
 for(const turn of turns){
  if(remaining<=0)throw Error('Phoenix free spins ended');boardOK(turn.board);const remainingBefore=remaining;remaining--;
  const added=turn.extraSpins??0;if(!Number.isSafeInteger(added)||added<0||remaining+added>1000||added&&turn.board.filter(id=>id===phoenixSymbol('bell-scatter')).length<3)throw Error('Invalid phoenix retrigger');
  const wilds=turn.board.flatMap((id,cell)=>id===phoenixSymbol('phoenix-wild')?[cell]:[]),stacks=[];
  // A stack is a contiguous vertical run. Two wilds separated by an ordinary
  // symbol are independent landings, even though they share a reel.
  for(let col=0;col<5;col++){
   let cells:number[]=[];
   for(let row=0;row<=3;row++){
    const cell=col+row*5;
    if(row<3&&turn.board[cell]===phoenixSymbol('phoenix-wild'))cells.push(cell);
    else{if(cells.length>=2)stacks.push({column:col,cells});cells=[];}
   }
  }
  const paid=winsCopy(turn.wins),remainingConsumed=remaining;remaining+=added;wins.push(...paid);stages.push({before:previous,board:[...turn.board],stacks,wilds,wins:paid,remainingBefore,remainingConsumed,remainingAfter:remaining,added});previous=[...turn.board];
 }
 if(remaining||!stages.length)throw Error('Incomplete phoenix free sequence');const payout=wins.reduce((sum,win)=>sum+win.amount,0);if(!Number.isSafeInteger(payout))throw Error('Phoenix payout overflow');
 return {bet,board:[...previous],payout,wins,phoenixFeature:{triggerBoard:[...triggerBoard],triggerCells,triggerWins,awarded,stages}};
}
