/** Source: provider's English in-game Game Help, game319, 2026-09-21.
 * Pure feature planning; not yet connected to a full Viking slot runtime.
 * Freya growth, effect geometry and WILD award overlap remain separate work. */
export type VikingDirectGift = 'thor'|'odin'|'heimdall';
export type VikingChargeAction = 'cascade'|'charge-effect'|'ragnarok'|'settle';
function randomIndex(rng:()=>number,length:number):number {
 const value=rng();
 if(!Number.isFinite(value)||value<0||value>=1)throw Error('Viking RNG outside [0,1)');
 return Math.floor(value*length);
}
/** Cells replaced only after the god's gift has triggered on a non-winning round.
 * Original English rules explicitly say Odin's pairs are VERTICAL. */
export function vikingDirectGiftCells(god:VikingDirectGift,rng:()=>number):number[]{
 if(god==='thor'){
  const count=5+randomIndex(rng,5),available=Array.from({length:49},(_,i)=>i),cells:number[]=[];
  while(cells.length<count)cells.push(available.splice(randomIndex(rng,available.length),1)[0]);
  return cells;
 }
 if(god==='heimdall')return Array.from({length:7},(_,row)=>row*7+randomIndex(rng,7));
 if(god==='odin'){
  const anchors=Array.from({length:42},(_,i)=>i);
  const first=anchors[randomIndex(rng,anchors.length)],cells=[first,first+7];
  const available=anchors.filter(cell=>!cells.includes(cell)&&!cells.includes(cell+7));
  const second=available[randomIndex(rng,available.length)];
  return [...cells,second,second+7];
 }
 throw Error('Unverified Viking gift geometry');
}
/** Evaluate AFTER displaying the current board's wins. A charged meter must
 * never interrupt unresolved cascades. Caller owns the meter/reset snapshots. */
export function vikingChargeAction(args:{hasWins:boolean;charge:number;effectPlayed:boolean;ragnarokPlayed:boolean}):VikingChargeAction {
 if(!Number.isSafeInteger(args.charge)||args.charge<0)throw Error('Invalid Viking charge');
 if(args.hasWins)return 'cascade';
 if(args.ragnarokPlayed)return 'settle';
 if(args.charge>=(args.effectPlayed?20:40))return 'ragnarok';
 if(!args.effectPlayed&&args.charge>=20)return 'charge-effect';
 return 'settle';
}
export function vikingRagnarokMultiplier(winningSymbols:number):number {
 if(!Number.isSafeInteger(winningSymbols)||winningSymbols<0)throw Error('Invalid Ragnarok symbol count');
 return winningSymbols>=80?15:winningSymbols>=60?5:winningSymbols>=40?3:winningSymbols>=20?2:1;
}
