import {isLocalMode} from './LocalMode';
import {native,sys} from 'cc';
import {PurchaseGateway,VerifiedPurchase,coinPacks} from './CoinShop';

type NativePurchase={status:'purchased'|'pending'|'cancelled'|'failed';productId?:string;purchaseToken?:string;orderId?:string;message?:string};
const VERIFY_URL='https://asia-northeast3-in-my-pocket-slots.cloudfunctions.net/verifyPlayPurchase';

/** Google Play Billing bridge. Google completes checkout; the server verifies,
 * consumes and credits each token exactly once before a wallet is accepted. */
export class AndroidPlayBilling implements PurchaseGateway{
 constructor(private uid:()=>string,private idToken:()=>Promise<string>){}
 get ready(){
  if(isLocalMode()||!sys.isNative||sys.os!==sys.OS.ANDROID)return false;
  try{return native.reflection.callStaticMethod('com/cocos/game/PocketBilling','ready','()Ljava/lang/String;')==='ready';}catch{return false;}
 }
 private invoke(method:'purchase'|'restore'|'poll',...args:string[]){
  if(isLocalMode())throw Error('Billing disabled in local mode');
  const signature='('+args.map(()=> 'Ljava/lang/String;').join('')+')Ljava/lang/String;';
  return native.reflection.callStaticMethod('com/cocos/game/PocketBilling',method,signature,...args) as string;
 }
 private async wait(id:string,timeout=180000):Promise<NativePurchase[]>{
  const started=Date.now();
  while(Date.now()-started<timeout){
   await new Promise(resolve=>setTimeout(resolve,250));
   const raw=this.invoke('poll',id);if(!raw||raw==='waiting')continue;
   const value=JSON.parse(raw);return Array.isArray(value)?value:[value];
  }
  throw Error('Google Play 결제 응답 시간이 초과되었습니다. 주문 내역에서 다시 확인해 주세요.');
 }
 private async verify(purchase:NativePurchase):Promise<VerifiedPurchase>{
  if(purchase.status==='pending')throw Error('결제가 보류 중입니다. Google Play에서 결제가 완료되면 다시 확인해 주세요.');
  if(purchase.status==='cancelled')throw Error('결제가 취소되었습니다.');
  if(purchase.status!=='purchased'||!purchase.productId||!purchase.purchaseToken)throw Error(purchase.message||'Google Play 결제를 완료하지 못했습니다.');
  if(!coinPacks.some(pack=>pack.id===purchase.productId))throw Error('등록되지 않은 상품입니다.');
  const token=await this.idToken();
  const response=await fetch(VERIFY_URL,{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},body:JSON.stringify({productId:purchase.productId,purchaseToken:purchase.purchaseToken})});
  const body=await response.json().catch(()=>({}));
  if(!response.ok)throw Error(body.error||'결제 검증 서버에서 구매를 확인하지 못했습니다.');
  return body as VerifiedPurchase;
 }
 async purchaseAndVerify(productId:string){
  const uid=this.uid();if(!uid)throw Error('로그인 후 구매해 주세요.');
  const id=Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
  if(this.invoke('purchase',id,productId,uid)!=='loading')throw Error('Google Play 결제를 시작하지 못했습니다.');
  const [purchase]=await this.wait(id);return this.verify(purchase);
 }
 async restorePurchases(){
  const uid=this.uid();if(!uid)return [];
  const id='restore-'+Date.now().toString(36);
  if(this.invoke('restore',id,uid)!=='loading')return [];
  const purchases=await this.wait(id,60000),verified:VerifiedPurchase[]=[];
  for(const purchase of purchases)if(purchase.status==='purchased')verified.push(await this.verify(purchase));
  return verified;
 }
}
