import {SlotMain,SlotConfig,SpinResult} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
import {HOGS_ART,HOGS_EXTRA_ART,HogsPig,HogsStage,hogsStart,hogsResolve,hogsSymbol as symbol} from './HogsFeature';
export class HogsPreviewSlot extends SlotMain {
 constructor(private readonly fixture='remix'){super();}
 readonly columns=5;rows=3;readonly mode='lines' as const;readonly paylines:number[][]=[];readonly bets=[...BET_LEVELS];
 readonly config:SlotConfig={id:'double-down-street',title:'골목 비트단',subtitle:'ALLEY BEAT CREW',tag:'전용 리스핀 체험',color:'#333349',accent:'#efb6cd',description:'돼지 6개 이상 · 리믹스 리스핀\n돼지와 보상은 다음 회전에도 고정\n초록 돼지는 매회 값 증가\n빨강 돼지는 다른 돼지 값 두 배\n금색 돼지는 무대 확장',symbols:HOGS_ART.map(art=>({id:symbol(art),name:art==='headphones'?'WILD':art.replace(/_/g,' '),color:'#efb6cd',weight:0,payout:0}))};
 artResource(id:string){const name=id.slice('double-down-street-'.length);if(![...HOGS_ART,...HOGS_EXTRA_ART].includes(name))throw Error('Unknown Hogs art');return 'slot-art-delivered-v1/double-down-street/v05/'+name;}
 spin():SpinResult{throw Error('Hogs first draft is free playback only');}
 demoSpin(bet:number):SpinResult{
  if(!this.bets.includes(bet))throw Error('Invalid bet');
  const triggerBoard=Array.from({length:15},(_,i)=>symbol(HOGS_ART[(i+i%5)%10]));
  if(this.fixture==='no-win')return {bet,board:triggerBoard,payout:0,wins:[]};
  const initial=hogsStart([0,2,4,6,8,10].map((cell,index)=>({cell,kind:index===0?'green':'pink',value:1}))),stages:HogsStage[]=[];let state=initial;
  initial.pigs.forEach(pig=>triggerBoard[pig.cell]=symbol(pig.kind+'_pig'));
  while(state.remaining>0){
   const landed:HogsPig[]=state.played===0?[{cell:12,kind:'red',value:2}]:state.played===1&&this.fixture!=='red-only'?[{cell:14,kind:'golden',value:2}]:[];
   const stage=hogsResolve(state,landed,{0:1},{12:[0,2,4]},{14:2});stages.push(stage);state=stage.after;
   if(state.played>20)throw Error('Hogs fixture did not finish');
  }
  const award={line:-1,symbol:symbol('pink_pig'),amount:state.pigs.reduce((sum,pig)=>sum+pig.value,0)*bet,cells:state.pigs.map(pig=>pig.cell)};
  const board=Array(state.rows*5).fill('double-down-street-void');state.pigs.forEach(pig=>board[pig.cell]=symbol(pig.kind+'_pig'));
  return {bet,board,payout:award.amount,wins:[award],hogsFeature:{initial,stages,final:state,award,triggerBoard}};
 }
}
