import {SpinResult,Win} from './SlotMain';
import {TumbleGame,TumbleFrame,indices,adjacent,randomIndex} from './TumbleCore';

export class ParrotFrontierSlot extends TumbleGame {
 readonly columns=8;readonly rows=8;readonly regularCount=4;readonly hasBonus=true;
 readonly config=this.configFor('parrot-frontier','앵무 개척단','PARROT FRONTIER',['붉은 열매','파란 열매','초록 열매','보라 열매','탐험 주화','승급 깃털','발굴 폭탄','보너스 지도','붉은 앵무','파란 앵무','초록 앵무','보라 앵무'],['0','1','2','3','coin','upgrade','bomb','scatter','bird0','bird1','bird2','bird3'],'6×6에서8×8로 확장. 네 앵무가 인접한 자기색 열매를 따라 이동·수집. 깃털은 열매 승급, 폭탄은 이웃 제거·영역 확장. 지도3개: 무료5회. 무료 중 크기·등급 유지, 지도3개 +2(총25회).',[16,16,16,16,2,2,2,2,0,0,0,0]);
 private run(bet:number,rng:()=>number,state:{size:number;grades:number[]},free:boolean){
  let board=this.draw(rng).map((s,c)=>c%8<state.size&&Math.floor(c/8)<state.size?s:this.id('void'));
  const birds=[0,state.size-1,(state.size-1)*8,(state.size-1)*8+state.size-1];birds.forEach((c,i)=>board[c]=this.id('bird'+i));
  const frames:TumbleFrame[]=[],badges=()=>Object.fromEntries(birds.map((c,i)=>[c,'L'+state.grades[i]]));let maps=0;
  this.frame(frames,board,'land',(free?'무료 탐험 · ':'')+state.size+'×'+state.size,{badges:badges(),stationary:birds});
  for(let step=0;step<100;step++){
   let moved=false;
   for(let i=0;i<4;i++){
    const from=birds[i],to=adjacent(from,8,64).find(c=>[this.id(i),this.id('coin'),this.id('upgrade'),this.id('bomb'),this.bonusSymbol!].includes(board[c]));if(to===undefined)continue;
    moved=true;const token=board[to],remove=new Set([from]),wins:Win[]=[];
    if(token===this.id(i))wins.push(this.prize(bet,.025*state.grades[i],[to],token));
    if(token===this.id('coin'))wins.push(this.prize(bet,.2,[to],token));
    if(token===this.id('upgrade'))state.grades[i]=Math.min(5,state.grades[i]+1);
    if(token===this.bonusSymbol)maps++;
    board[to]=this.id('bird'+i);board[from]=this.id('void');birds[i]=to;
    this.frame(frames,board,'move','앵무 '+(i+1)+' 이동·수집',{moves:[{from,to,symbol:this.id('bird'+i)}],cells:[to],badges:badges()});
    this.frame(frames,board,'collect',token===this.id('upgrade')?'열매 등급 상승':token===this.bonusSymbol?'지도 '+maps+'/3':token===this.id('bomb')?'폭탄 발굴':token===this.id('coin')?'탐험 주화 지급':'열매 수집 지급',{wins,cells:[to],badges:badges()});
    if(token===this.id('bomb')){
     const blast=adjacent(to,8,64).filter(c=>!birds.includes(c)&&board[c]!==this.id('void'));blast.forEach(c=>remove.add(c));
     if(state.size<8){state.size++;for(let c=0;c<64;c++)if(c%8<state.size&&Math.floor(c/8)<state.size&&board[c]===this.id('void')&&!birds.includes(c))remove.add(c);}
     this.frame(frames,board,'transform','폭탄 발굴 · '+state.size+'×'+state.size+' 개방',{cells:Array.from(remove),badges:badges()});
    }
    const next=this.gravity(board,remove,rng,new Set(birds),c=>c%8<state.size&&Math.floor(c/8)<state.size);board=next.board;
    this.frame(frames,board,'drop','수집 빈칸 낙하',{moves:next.moves,badges:badges()});
   }if(!moved)break;if(step===99)this.frame(frames,board,'state','탐험100단계 안전 종료',{badges:badges()});
  }return{round:this.round(bet,frames),maps};
 }
 rawSpin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid bet');const state={size:6,grades:[1,1,1,1]},base=this.run(bet,rng,state,false);if(base.maps<3)return this.finish([base.round]);const rounds=[base.round];let left=5,awarded=5;while(left>0){left--;const next=this.run(bet,rng,state,true),extra=next.maps>=3?Math.min(2,25-awarded):0;left+=extra;awarded+=extra;next.round.freeSpinsRemaining=left;next.round.freeSpinsAdded=extra||undefined;rounds.push(next.round);}return this.finish(rounds,{freeSpinsAwarded:5});}
}

export class GoldenReactionSlot extends TumbleGame {
 readonly columns=8;readonly rows=8;readonly hasBonus=true;
 readonly config=this.configFor('golden-reaction-lab','황금 반응 연구소','GOLDEN REACTION LAB',['붉은 시약','금빛 시약','초록 시약','청색 시약','보라 시약','흰 시약','반응 WILD','반응핵'],['0','1','2','3','4','5','wild','nucleus'],'8×8 · 연결5개. 색 칸 당첨 뒤 정해진 순서로 전판 교체→WILD→2×2→3×3→추가WILD. 반응핵 착지는 인접색 변환. 한 회전25개 수집: 골드피버, 5단계×2/4/6/8/10. 각 단계25개 수집 시 다음 단계.',[12,12,12,12,12,12,.8,.6]);
 private run(bet:number,rng:()=>number,multi:number,fever:boolean){let board=this.draw(rng);const frames:TumbleFrame[]=[],marks=[0,15,24,47,60],pending=new Set<number>(fever?[0,1,2,3,4]:[]),used=new Set<number>();let collected=0;
  this.frame(frames,board,'land',fever?'골드피버 ×'+multi:'반응 표식 대기',{marks});
  for(let step=0;step<45;step++){
   const nuclei=indices(board,this.id('nucleus'));if(nuclei.length){const cells=new Set<number>();for(const c of nuclei){const color=this.id(randomIndex(rng,6));[c,...adjacent(c,8,64)].forEach(n=>{board[n]=color;cells.add(n);});}this.frame(frames,board,'transform','반응핵 · 인접색 변환',{cells:Array.from(cells),marks});}
   const wins=this.clusters(board,bet,multi);if(wins.length){const removed=new Set(wins.flatMap(w=>w.cells));collected+=removed.size;marks.forEach((c,i)=>{if(removed.has(c)&&!used.has(i))pending.add(i);});this.frame(frames,board,'win','반응 수집 '+collected+' · ×'+multi,{wins,cells:Array.from(removed),marks});const next=this.gravity(board,removed,rng);board=next.board;this.frame(frames,board,'drop','반응 낙하',{moves:next.moves,marks});if(step===44)this.frame(frames,board,'state','반응45단계 안전 종료',{marks});continue;}
   const effect=Array.from(pending).sort()[0];if(effect===undefined)break;pending.delete(effect);used.add(effect);const cells:number[]=[];
   if(effect===0){board=this.draw(rng);cells.push(...board.map((_,c)=>c));}
   else if(effect===1||effect===4){for(let i=0;i<(effect===1?3:6);i++){const c=randomIndex(rng,64);board[c]=this.wild!;cells.push(c);}}
   else{const size=effect===2?2:3,x=randomIndex(rng,9-size),y=randomIndex(rng,9-size),symbol=this.id(randomIndex(rng,6));for(let r=0;r<size;r++)for(let c=0;c<size;c++){const at=(y+r)*8+x+c;board[at]=symbol;cells.push(at);}}
   this.frame(frames,board,'transform',['전판 반응','WILD 반응','사각 반응','거대 반응','마지막 WILD 반응'][effect],{cells,marks});if(step===44)this.frame(frames,board,'state','반응45단계 안전 종료',{marks});
  }return{round:this.round(bet,frames),collected};
 }
 rawSpin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid bet');const base=this.run(bet,rng,1,false);if(base.collected<25)return this.finish([base.round]);const rounds=[base.round];for(let level=1;level<=5;level++){const next=this.run(bet,rng,level*2,true);next.round.roundLabel='GOLD FEVER · '+level+'단계';rounds.push(next.round);if(next.collected<25)break;}return this.finish(rounds,{featureOnly:true});}
}

export class PrismSplitSlot extends TumbleGame {
 readonly columns=5;readonly rows=8;readonly hasBonus=true;
 readonly config=this.configFor('prism-split-forge','프리즘 분할 공방','PRISM SPLIT FORGE',['붉은 프리즘','황색 프리즘','초록 프리즘','청색 프리즘','보라 프리즘','흰 프리즘','분광 WILD','공방 문'],['0','1','2','3','4','5','wild','scatter'],'5릴 · 왼쪽3릴부터 Ways. 위 보조릴과 같은 심볼 당첨 시 해당 릴 칸 분할, 최대7칸. 보조릴 배수는 낙하마다 +1(최대7). 문3개: 무료6회, 무료 중 릴 배수 유지. 자체 분할 각색.');
 private run(bet:number,rng:()=>number,multipliers:number[],free:boolean){const heights=[3,4,4,4,3],top=[this.id(randomIndex(rng,6)),this.id(randomIndex(rng,6)),this.id(randomIndex(rng,6))];let board=this.draw(rng).map((s,c)=>Math.floor(c/5)>=8-heights[c%5]?s:this.id('void'));const frames:TumbleFrame[]=[],badges=()=>Object.fromEntries([1,2,3].map(c=>[c,'×'+multipliers[c]]));
  const visual=()=>{const tiles=[];for(let col=0;col<5;col++)for(let row=0;row<heights[col];row++)tiles.push({cell:(8-heights[col]+row)*5+col,x:col+.5,y:1.25+(row+.5)*6.75/heights[col],w:1,h:6.75/heights[col]});return [...tiles,...[1,2,3].map(cell=>({cell,x:cell+.5,y:.5,w:1,h:1}))];};
  const shown=()=>{const b=[...board];top.forEach((s,i)=>{b[i+1]=s;});return b;};
  this.frame(frames,shown(),'land',free?'무료 공방 · 배수 유지':'보조릴과 같은 색을 찾으세요',{tiles:visual(),badges:badges()});let scatters=indices(board,this.bonusSymbol!).length;
  for(let step=0;step<30;step++){
   const wins:Win[]=[];for(let s=0;s<6;s++){const cells:number[]=[],counts:number[]=[];let m=1;
    for(let col=0;col<5;col++){const hits=indices(board,this.id(s)).concat(indices(board,this.wild!)).filter(c=>c%5===col),extra=col>0&&col<4&&top[col-1]===this.id(s)?1:0;if(!hits.length&&!extra)break;counts.push(hits.length+extra);cells.push(...hits,...(extra?[col]:[]));m*=multipliers[col];}
    if(counts.length>=3)wins.push(this.prize(bet,(.004+.001*(6-s))*[0,0,0,1,2,4][counts.length]*counts.reduce((n,c)=>n*c,1)*m,cells,this.id(s)));}
   if(!wins.length)break;const remove=new Set(wins.flatMap(w=>w.cells).filter(c=>c>=5));this.frame(frames,shown(),'win','분할 Ways 지급',{wins,cells:wins.flatMap(w=>w.cells),tiles:visual(),badges:badges()});
   for(let col=1;col<=3;col++)if(Array.from(remove).some(c=>c%5===col&&board[c]===top[col-1])&&heights[col]<7){heights[col]++;const c=(8-heights[col])*5+col;board[c]=this.id(randomIndex(rng,6));this.frame(frames,shown(),'transform',(col+1)+'릴 분할 · '+heights[col]+'칸',{cells:[c],tiles:visual(),badges:badges()});}
   const next=this.gravity(board,remove,rng);board=next.board;for(let col=1;col<=3;col++)multipliers[col]=Math.min(7,multipliers[col]+1);this.frame(frames,shown(),'drop','분할된 칸 낙하',{moves:next.moves,tiles:visual(),badges:badges()});scatters=Math.max(scatters,indices(board,this.bonusSymbol!).length);if(step===29)this.frame(frames,shown(),'state','연쇄30회 안전 종료',{tiles:visual(),badges:badges()});
  }return{round:this.round(bet,frames),scatters};
 }
 rawSpin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid bet');const m=[1,1,1,1,1],base=this.run(bet,rng,m,false);if(base.scatters<3)return this.finish([base.round]);m.fill(1);const rounds=[base.round];for(let left=5;left>=0;left--){const next=this.run(bet,rng,m,true);next.round.freeSpinsRemaining=left;rounds.push(next.round);}return this.finish(rounds,{freeSpinsAwarded:6});}
}

export class GlyphArchiveSlot extends TumbleGame {
 readonly columns=6;readonly rows=5;readonly hasBonus=true;readonly bonusChoiceCount=2;
 readonly config=this.configFor('glyph-archive','문양 보관소','GLYPH ARCHIVE',['태양 문양','달 문양','연꽃 문양','물결 문양','날개 문양','모래 문양','서기관 WILD','봉인 지도'],['0','1','2','3','4','5','wild','scatter'],'6×5 · 연결5개. 문양 위치에서 심볼을 기록하고 종료 후 해당 위치 변환→추가 낙하. 지도3개: 무료7회, 위치 고정/심볼 고정 선택. 지도4개: 둘 다. 무료 지도마다 +1(총30회).');
 private run(bet:number,rng:()=>number,state:{positions:Set<number>;symbols:Map<number,string>},mode:number,free:boolean){let board=this.draw(rng);const frames:TumbleFrame[]=[];if(!free||mode===1)state.positions=new Set([randomIndex(rng,30),randomIndex(rng,30),randomIndex(rng,30)]);if(!free||mode===0)state.symbols.clear();
  const heldAtStart=free&&mode!==0?Array.from(state.symbols.keys()):[];for(const [c,s]of state.symbols)board[c]=s;
  for(const c of state.positions)if(board[c]!==this.bonusSymbol)state.symbols.set(c,board[c]);
  const count=indices(board,this.bonusSymbol!).length;let transformed=false;
  this.frame(frames,board,'land',free?['문양 위치 유지','기록 심볼 유지','위치+심볼 유지'][mode]:'문양 기록',{stationary:heldAtStart,marks:Array.from(state.positions),badges:Object.fromEntries(Array.from(state.symbols).map(([c])=>[c,'기록']))});
  for(let step=0;step<30;step++){
   const pinned=free&&mode!==0?new Set(state.symbols.keys()):new Set<number>();const wins=this.clusters(board,bet).filter(w=>w.cells.some(c=>!pinned.has(c)));if(wins.length){const remove=new Set(wins.flatMap(w=>w.cells).filter(c=>!pinned.has(c)));this.frame(frames,board,'win','문양 클러스터 지급',{wins,cells:Array.from(remove),marks:Array.from(state.positions)});const next=this.gravity(board,remove,rng,pinned);board=next.board;this.frame(frames,board,'drop','기록 사이로 낙하',{moves:next.moves,marks:Array.from(state.positions)});if(step===29)this.frame(frames,board,'state','연쇄30회 안전 종료',{marks:Array.from(state.positions)});continue;}
   if(transformed)break;transformed=true;const cells:number[]=[];for(const c of state.positions){const symbol=state.symbols.get(c);if(symbol&&board[c]!==symbol){board[c]=symbol;cells.push(c);}}if(!cells.length)break;this.frame(frames,board,'transform','스핀 종료 · 기록 문양 복원 후 재판정',{cells,marks:Array.from(state.positions)});
  }return{round:this.round(bet,frames),count};
 }
 rawSpin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid bet');const state={positions:new Set<number>(),symbols:new Map<number,string>()},base=this.run(bet,rng,state,0,false);if(base.count<3)return this.finish([base.round]);
  const results=[0,1].map(choice=>{const local={positions:new Set(state.positions),symbols:new Map(state.symbols)},rounds=[structuredClone(base.round)];let left=7,awarded=7;
   while(left>0){left--;const next=this.run(bet,rng,local,base.count>=4?2:choice,true),extra=Math.min(next.count,30-awarded);left+=extra;awarded+=extra;next.round.freeSpinsRemaining=left;next.round.freeSpinsAdded=extra||undefined;rounds.push(next.round);}return this.finish(rounds,{freeSpinsAwarded:7});});
  return{...results[0],featureChoices:{title:base.count>=4?'슈퍼 문양 · 두 효과 유지':'문양 보관 방식',labels:['위치 유지','심볼 유지'],results,defaultIndex:0}};
 }
}
